"""Weekly timesheet rows built from a list of shifts."""

from collections import Counter

from hourglass.errors import ProjectError
from hourglass.schedule import worker_minutes


def _validate(shifts):
    if not shifts:
        raise ProjectError("no shifts to total")
    for shift in shifts:
        if not shift.worker.strip():
            raise ProjectError("shift has no worker")


def _busiest(minutes):
    return sorted(
        minutes,
        key=lambda name: (-minutes[name], name),
    )


def _line(name, count, minutes):
    hours = minutes / 60
    return f"{name}: {count} shifts, {hours:.1f} hours"


def _render(shifts):
    minutes = worker_minutes(shifts)
    counts = Counter(shift.worker for shift in shifts)
    return [
        _line(name, counts[name], minutes[name])
        for name in _busiest(minutes)
    ]


# ---
def timesheet_lines(shifts):
    """One line per worker, busiest first."""
    shifts = list(shifts)
    _validate(shifts)
    return _render(shifts)

